(()=>{'use strict';const $=id=>document.getElementById(id),form=$('campaign-form'),names=['Instagram','Facebook','TikTok','X','LinkedIn','YouTube','Pinterest'];let media=[],id='',records=[],sourceStudioJobId='';const el=(t,text)=>{const e=document.createElement(t);if(text)e.textContent=text;return e;},say=t=>$('campaign-status').textContent=t;
async function api(method='GET',body){const r=await fetch('/api/studio/campaigns',{method,headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})}),d=await r.json();if(!r.ok)throw Error(d.error);return d;}
function fields(posts=[]){const host=$('campaign-platforms');host.replaceChildren();for(const name of names){const p=posts.find(p=>p.platform===name),card=el('article');card.className='record';card.dataset.platform=name;const label=el('label'),check=el('input');check.type='checkbox';check.dataset.field='selected';check.checked=!!p;check.style.width='auto';label.append(check,document.createTextNode(' '+name));card.append(label);const body=el('div');body.hidden=!p;check.onchange=()=>body.hidden=!check.checked;const captionLabel=el('label','Caption for '+name),caption=el('textarea');caption.dataset.field='caption';caption.maxLength=10000;caption.rows=4;caption.value=p?.caption||'';captionLabel.append(caption);body.append(captionLabel);const assetLabel=el('label','Image or video'),asset=el('select');asset.dataset.field='mediaId';asset.append(new Option('No media selected',''));media.forEach(m=>asset.append(new Option(m.name,m.id)));asset.value=p?.mediaId||'';assetLabel.append(asset);body.append(assetLabel);const note=el('p',name==='YouTube'?'Video, title and audience selection are required before publishing.':name==='Pinterest'?'An image and Pinterest board are required before publishing.':['Instagram','TikTok'].includes(name)?'Choose an image or video. Platform-specific formats still require provider review.':'Review your caption, format and account before publishing.');body.append(note);for(const [key,title]of name==='YouTube'?[['title','Video title'],['audience','Audience: made for kids / not made for kids']]:name==='Pinterest'?[['board','Pinterest board']]:[]){const l=el('label',title),input=el('input');input.dataset.field=key;input.value=p?.[key]||'';input.maxLength=150;l.append(input);body.append(l);}card.append(body);host.append(card);}}
function payload(){const data=Object.fromEntries(new FormData(form));return {sourceStudioJobId,title:data.title,brief:data.brief,approved:form.elements.approved.checked,scheduledAt:data.scheduledAt?new Date(data.scheduledAt+':00+02:00').toISOString():null,posts:[...$('campaign-platforms').children].filter(c=>c.querySelector('[data-field="selected"]').checked).map(c=>({platform:c.dataset.platform,...Object.fromEntries([...c.querySelectorAll('[data-field]')].filter(e=>e.dataset.field!=='selected').map(e=>[e.dataset.field,e.value]))}))};}
function render(){const host=$('campaign-records');host.replaceChildren();for(const r of records){const p=r.payload,card=el('article');card.className='record';card.append(el('h3',p.title),el('p',r.status),el('p',p.posts.map(p=>p.platform).join(' · ')),el('p',p.scheduledAt?'Planned: '+new Date(p.scheduledAt).toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'})+' SAST · Not scheduled':'No publishing time selected'));const edit=el('button','Edit captions & time');edit.onclick=()=>{id=r.id;sourceStudioJobId=p.sourceStudioJobId||'';form.elements.title.value=p.title;form.elements.brief.value=p.brief;form.elements.approved.checked=p.approved;form.elements.scheduledAt.value=p.scheduledAt?new Date(Date.parse(p.scheduledAt)+7200000).toISOString().slice(0,16):'';fields(p.posts);form.scrollIntoView({behavior:'smooth'});};const exportBtn=el('button','Export platform content');exportBtn.onclick=()=>{const data={format:'bonga-platform-campaign-v1',...p,status:r.status,note:'Provider-neutral content brief. This is not a scheduled post or an official Polsia import format.'};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=el('a');a.href=u;a.download='bonga-campaign.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};const publish=el('button','Check & post to platforms');publish.onclick=async()=>{publish.disabled=true;try{const response=await fetch('/api/studio/campaigns',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'publish',id:r.id})}),d=await response.json();say(d.error||d.status);await refresh();}catch(e){say(e.message);}finally{publish.disabled=false;}};const remove=el('button','Delete draft');remove.onclick=async()=>{if(!confirm('Delete this saved campaign draft?'))return;try{await api('DELETE',{id:r.id});await refresh();}catch(e){say(e.message);}};edit.dataset.campaignId=r.id;if(p.sourceStudioJobId)card.append(el('p','Linked to your Creative Studio job.'));card.append(edit,exportBtn,publish,remove);for(const post of p.posts){const details=el('details'),summary=el('summary',post.platform+' caption');details.append(summary,el('p',post.caption));card.append(details);}host.append(card);}if(!records.length)host.append(el('p','No saved campaigns yet.'));}
async function refresh(){try{records=(await api()).campaigns;render();const target=sessionStorage.getItem('bonga-open-campaign');if(target){const edit=[...document.querySelectorAll('[data-campaign-id]')].find(b=>b.dataset.campaignId===target);if(edit){edit.click();sessionStorage.removeItem('bonga-open-campaign');}}}catch(e){say(e.message);}}
window.addEventListener('studio-campaign-open',e=>{sessionStorage.setItem('bonga-open-campaign',e.detail);refresh();});form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"]')||form.querySelector('button:not([type])');button.disabled=true;try{const result=await api('POST',{id,payload:payload()});id=result.id;say('Campaign cloud saved. No posts have been scheduled or published.');await refresh();}catch(e){say(e.message);}finally{button.disabled=false;}};$('campaign-reset').onclick=()=>{id='';sourceStudioJobId='';form.reset();fields();say('New campaign draft.');};$('campaign-polsia').onclick=async()=>{try{const r=await fetch('/api/studio/campaigns/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({brief:form.elements.brief.value})}),d=await r.json();$('campaign-provider-status').textContent=d.error||'No content generated.';}catch{$('campaign-provider-status').textContent='Polsia connection unavailable.';}};(async()=>{try{const r=await fetch('/api/designer/media'),d=await r.json();if(r.ok)media=d.files.filter(m=>/^(image|video)\//.test(m.content_type));}catch{}fields();refresh();})();
})();
